#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    cin >> N;

    // We need the smallest k such that:
    // k(k+1)/2 ≡ 0 (mod N)
    //
    // Let M = 2N. Then we need:
    // k(k+1) ≡ 0 (mod 2N)
    //
    // Since gcd(k, k+1) = 1, every prime-power factor of 2N must divide
    // entirely into either k or k+1.
    //
    // If 2N = a * b with gcd(a, b) = 1, then choosing
    // k ≡ 0 (mod a), k ≡ -1 (mod b)
    // gives a valid solution, unique modulo ab = 2N by CRT.
    //
    // So we factor 2N into prime powers, assign each prime power to either
    // a or b, and for every such coprime split compute the smallest positive
    // CRT solution. The minimum over all splits is the answer.

    long long M = 2 * N;

    vector<long long> pp;
    long long x = M;
    for (long long p = 2; p * p <= x; ++p) {
        if (x % p == 0) {
            long long cur = 1;
            while (x % p == 0) {
                x /= p;
                cur *= p;
            }
            pp.push_back(cur);
        }
    }
    if (x > 1) pp.push_back(x);

    long long ans = LLONG_MAX;
    int m = (int)pp.size();

    // Enumerate which prime powers go into a; the rest go into b.
    for (int mask = 0; mask < (1 << m); ++mask) {
        long long a = 1, b = 1;
        for (int i = 0; i < m; ++i) {
            if (mask & (1 << i)) a *= pp[i];
            else b *= pp[i];
        }

        // Need k ≡ 0 (mod a), k ≡ -1 (mod b)
        // Write k = a * t, then a*t ≡ -1 (mod b)
        // Since gcd(a,b)=1, inverse of a mod b exists.
        long long k;
        if (b == 1) {
            k = a; // smallest positive multiple of a
        } else if (a == 1) {
            k = b - 1; // since k ≡ -1 (mod b)
            if (k == 0) k = b;
        } else {
            // Extended gcd for inverse
            auto egcd = [&](auto&& self, long long A, long long B) -> array<long long,3> {
                if (B == 0) return {A, 1, 0};
                auto r = self(self, B, A % B);
                long long g = r[0], x1 = r[1], y1 = r[2];
                return {g, y1, x1 - (A / B) * y1};
            };

            auto r = egcd(egcd, a, b);
            long long invA = r[1] % b;
            if (invA < 0) invA += b;

            long long t = (b - 1) * invA % b; // t ≡ -invA mod b
            k = a * t;
            if (k == 0) k = M; // smallest positive representative
        }

        ans = min(ans, k);
    }

    cout << ans << '\n';
    return 0;
}

