long long gcd(long long a, long long b) {
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    long long N;
    scanf("%lld", &N);

    long long M = 2 * N;
    long long best = M; // upper bound (k = 2N works because M divides 2N*(2N+1)? Actually not always, but we'll compute properly)

    // Try all divisors d of M
    for (long long d = 1; d * d <= M; d++) {
        if (M % d == 0) {
            long long d1 = d;
            long long d2 = M / d;

            // Case 1: d divides k, M/d divides k+1
            // Find smallest k such that k % d == 0 and (k+1) % (M/d) == 0
            // k ≡ 0 (mod d), k ≡ -1 (mod M/d)
            // Solve using CRT when gcd(d, M/d) == 1 (always true since they're coprime factors of M)
            // k = 0 + d * t, find t such that d*t ≡ -1 (mod M/d)
            // t ≡ inv(d mod M/d) * (-1) mod M/d

            // We can just brute search up to d * (M/d) = M, but that's O(M). Instead use modular inverse.
            long long mod1 = d;
            long long mod2 = M / d;

            if (gcd(mod1, mod2) == 1) {
                // Find inverse of mod1 modulo mod2
                long long inv = 1;
                for (long long x = 1; x < mod2; x++) {
                    if ((mod1 * x) % mod2 == 1) {
                        inv = x;
                        break;
                    }
                }
                long long t = (mod2 - 1) * inv % mod2;
                long long k = mod1 * t;
                if (k == 0) k = M; // k must be positive
                if (k < best) best = k;
            }

            // Case 2: M/d divides k, d divides k+1
            mod1 = M / d;
            mod2 = d;
            if (gcd(mod1, mod2) == 1) {
                long long inv = 1;
                for (long long x = 1; x < mod2; x++) {
                    if ((mod1 * x) % mod2 == 1) {
                        inv = x;
                        break;
                    }
                }
                long long t = (mod2 - 1) * inv % mod2;
                long long k = mod1 * t;
                if (k == 0) k = M;
                if (k < best) best = k;
            }
        }
    }

    printf("%lld\n", best);
    return 0;
}

