int main() {
    long long N;
    scanf("%lld", &N);

    for (long long k = 1; k <= 2 * N; k++) {
        // Compute k*(k+1)/2 mod N
        // k*(k+1) is always even
        long long half;
        if (k % 2 == 0) {
            // (k/2) * (k+1) mod N
            half = (k / 2 % N) * ((k + 1) % N) % N;
        } else {
            // k * ((k+1)/2) mod N
            half = (k % N) * ((k + 1) / 2 % N) % N;
        }
        if (half == 0) {
            printf("%lld\n", k);
            return 0;
        }
    }

    return 0;
}

