                // Case 1: k = d
                long k = d;
                if ((k * (k + 1)) % M == 0) {
                    ans = Math.min(ans, k);
                }

                // Case 2: k = d - 1
                if (d > 1) {
                    k = d - 1;
                    if ((k * (k + 1)) % M == 0) {
                        ans = Math.min(ans, k);
                    }
                }

                // Also consider the counterpart divisor
                long d2 = M / d;
                // k = d2
                k = d2;
                if ((k * (k + 1)) % M == 0) {
                    ans = Math.min(ans, k);
