import java.util.*;

public class Main {
    static long gcd(long a, long b) {
        while (b != 0) { long t = b; b = a % b; a = t; }
        return a;
    }

    // Extended gcd: returns {g, x, y} such that a*x + b*y = g
    static long[] extgcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = extgcd(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a/b)*r[2]};
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long M = 2 * N;

        // Find all divisors of M
        List<Long> divs = new ArrayList<>();
        for (long i = 1; i * i <= M; i++) {
            if (M % i == 0) {
                divs.add(i);
                if (i != M / i) divs.add(M / i);
            }
        }

        long ans = Long.MAX_VALUE;
        for (long a : divs) {
            long b = M / a;
            if (gcd(a, b) != 1) continue;
            // k ≡ 0 (mod a), k ≡ -1 (mod b)
            // k = a * t, a*t ≡ -1 (mod b)
            // t ≡ -1 * inv(a) (mod b)
            long[] eg = extgcd(a, b);
            // a * eg[1] + b * eg[2] = 1
            long inv_a = eg[1] % b;
            if (inv_a < 0) inv_a += b;
            long t = ((-1) * inv_a % b + b) % b;
            long k = a * t;
            if (k == 0) k = M; // k must be positive
            if (k > 0 && k < ans) ans = k;
        }

        System.out.println(ans);
    }
}

