from math import gcd

def solve(N):
    M = 2 * N
    # Factor M
    factors = {}
    temp = M
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    prime_powers = [p**e for p, e in factors.items()]
    n = len(prime_powers)

    best = float('inf')

    # Enumerate all 2^n subsets: subset goes to a, rest goes to b
    for mask in range(1 << n):
        a, b = 1, 1
        for i in range(n):
            if mask & (1 << i):
                a *= prime_powers[i]
            else:
                b *= prime_powers[i]
        # k ≡ 0 (mod a), k ≡ -1 (mod b)
        # CRT: find k mod M
        # k = a * t, a*t ≡ -1 (mod b)
        if b == 1:
            k = 0  # k ≡ 0 (mod a), any k=a,2a,...
            k = a
        else:
            g = gcd(a, b)
            if (-1) % g != 0:
                pass
            else:
                # solve a*t ≡ -1 (mod b)
                inv = pow(a % b, -1, b) if gcd(a,b)==1 else None
                if inv is not None:
                    t = ((-1) * inv) % b
                    k = a * t
                    k = k % M
                    if k == 0:
                        k = M
                    best = min(best, k)

    return best

